import React, { useState } from "react";
import {
  ListItem,
  ListItemText,
  IconButton,
  Checkbox,
  ListItemIcon,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";
// import EditIcon from "@mui/icons-material/Edit";

function TodoItem({ todo, toggleTodo, deleteTodo }) {
  const [open, setOpen] = useState(false);

  const [openEdit, setOpenEdit] = useState(false);
  const [editValue, setEditValue] = useState(todo.text);

  const handleOpen = () => setOpen(true);
  const handleClose = () => setOpen(false);

  const handleDelete = () => {
    console.log("deletando tarefa com ID", todo.id);
    deleteTodo(todo.id);
    handleClose();
  };

  const createdAtText = todo.createdAt
    ? new Date(todo.createdAt).toLocaleString()
    : "";
  return (
    <>
      <ListItem
        secondaryAction={
          <IconButton edge="end" color="error" onClick={handleOpen}>
            <DeleteIcon />
            <EditIcon />
          </IconButton>
        }
      >
        <ListItemIcon>
          <Checkbox
            edge="start"
            checked={todo.completed}
            onChange={() => toggleTodo(todo.id)}
          />
        </ListItemIcon>

        <ListItemText
          primary={todo.text}
          secondary={createdAtText ? `Adicionado em ${createdAtText}` : ""}
          sx={{
            textDecoration: todo.completed ? "line-through" : "none",
            color: todo.completed ? "gray" : "inherit",
            wordBreak: "break-word",
            whiteSpace: "pre-wrap",
            overflowWrap: "break-word",
          }}
        />
      </ListItem>

      <Dialog open={open} onClose={handleClose}>
        <DialogTitle>Excluir tarefa recorrente</DialogTitle>
        <DialogContent>Você quer mesmo excluir está tarefa</DialogContent>
        <DialogActions>
          <Button onClick={handleClose} color="primary">
            Cancelar
          </Button>
          <Button onClick={handleDelete} color="error" variant="contained">
            Deleter
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
}

export default TodoItem;
